test("ノードを指していれば、掘る量どおりのノードを選ぶ", () => {
  const name = DocumentSelection.nameToSelectAt(
    setupSelection(),
    ["label", "card", "home"],
    SelectionDigs.Deepest,
  );

  expect(name).toEqual(Option.some("label"));
});

test("artboard の背景を指すと、その artboard を選ぶ", () => {
  const name = DocumentSelection.nameToSelectAt(
    setupSelection(),
    ["home"],
    SelectionDigs.NoDeeper,
  );

  expect(name).toEqual(Option.some("home"));
});

test("ロック中のノードしか無い枝を指すと、その artboard を選ぶ", () => {
  const name = DocumentSelection.nameToSelectAt(
    setupSelection(),
    ["sealed-title", "sealed", "home"],
    SelectionDigs.Deepest,
  );

  expect(name).toEqual(Option.some("home"));
});

test("押された位置を載せている artboard は、辿った名前のうちの artboard になる", () => {
  const name = DocumentSelection.artboardNameAt(setupSelection(), [
    "label",
    "card",
    "home",
  ]);

  expect(name).toEqual(Option.some("home"));
});

test("掘る量が違えば等しくない", () => {
  const a = Pointing.create(["label", "card", "home"], SelectionDigs.NoDeeper);
  const b = Pointing.create(["label", "card", "home"], SelectionDigs.Deepest);

  expect(Pointing.equals(a, b)).toBe(false);
});

test("キャンバスの外と枠の外は等しくない", () => {
  expect(Pointing.equals(Pointing.Outside, Pointing.Nothing)).toBe(false);
});

test("選択の内側を指すと、選択から親の内側の縁までを測る", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.create(
      ["label", "cell", "row", "card", "home"],
      SelectionDigs.NoDeeper,
    ),
  );

  expect(pair).toEqual(
    Option.some({ kind: "within", inner: "row", outer: "card" }),
  );
});

test("兄弟を指すと、兄弟との横並びを測る", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.create(["chip", "card", "home"], SelectionDigs.NoDeeper),
  );

  expect(pair).toEqual(
    Option.some({ kind: "beside", from: "row", to: "chip" }),
  );
});

test("兄弟の子を指しても、兄弟との横並びを測る", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.create(
      ["chip-icon", "chip", "card", "home"],
      SelectionDigs.NoDeeper,
    ),
  );

  expect(pair).toEqual(
    Option.some({ kind: "beside", from: "row", to: "chip" }),
  );
});

test("⌘ を押して選択の内側を指すと、いちばん内側の子孫から選択の内側の縁までを測る", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.create(
      ["label", "cell", "row", "card", "home"],
      SelectionDigs.Deepest,
    ),
  );

  expect(pair).toEqual(
    Option.some({ kind: "within", inner: "label", outer: "row" }),
  );
});

test("⌘ を押して兄弟の子を指すと、その子との横並びを測る", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.create(
      ["chip-icon", "chip", "card", "home"],
      SelectionDigs.Deepest,
    ),
  );

  expect(pair).toEqual(
    Option.some({ kind: "beside", from: "row", to: "chip-icon" }),
  );
});

test("深さ 3 のノードを選んで親の背景を指すと、クリックの規則どおり artboard 直下の祖先の内側の縁までを測る", () => {
  // 親（`row`）の縁とは答えが違う
  const pair = DistancePair.create(
    selectionDistanceTree(["cell"]),
    Pointing.create(["row", "card", "home"], SelectionDigs.NoDeeper),
  );

  expect(pair).toEqual(
    Option.some({ kind: "within", inner: "cell", outer: "card" }),
  );
});

test("深さ 2 のノードを選んで自分の artboard の背景を指すと、artboard の内側の縁までを測る", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.create(["home"], SelectionDigs.NoDeeper),
  );

  expect(pair).toEqual(
    Option.some({ kind: "within", inner: "row", outer: "home" }),
  );
});

test("深さ 2 のノードを選んで別の artboard のノードを指すと、親の内側の縁までを測る", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.create(["slot", "settings"], SelectionDigs.NoDeeper),
  );

  expect(pair).toEqual(
    Option.some({ kind: "within", inner: "row", outer: "card" }),
  );
});

test("artboard の枠の外を指すと、親の内側の縁までを測る", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.Nothing,
  );

  expect(pair).toEqual(
    Option.some({ kind: "within", inner: "row", outer: "card" }),
  );
});

test("キャンバスの外を指していると、何も測らない", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.Outside,
  );

  expect(pair).toEqual(Option.none);
});

test("内側の縁を測る組で、包む側だけが違えば等しくない", () => {
  const isEqual = DistancePair.equals(
    { kind: "within", inner: "row", outer: "card" },
    { kind: "within", inner: "row", outer: "home" },
  );

  expect(isEqual).toBe(false);
});

test("複数選択では、兄弟を指しても何も測らない", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row", "title"]),
    Pointing.create(["chip", "card", "home"], SelectionDigs.NoDeeper),
  );

  expect(pair).toEqual(Option.none);
});

test("ロック中の兄弟を指しても、その兄弟は相手にならない", () => {
  // ロックを見なければ `sealed` との横並びになる
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.create(["sealed", "card", "home"], SelectionDigs.NoDeeper),
  );

  expect(pair).toEqual(
    Option.some({ kind: "within", inner: "row", outer: "card" }),
  );
});

test("⌘ を押してロック中のノードの中を指すと、そのすぐ外側のノードを相手にする", () => {
  const pair = DistancePair.create(
    selectionDistanceTree(["row"]),
    Pointing.create(
      ["sealed-mark", "sealed", "card", "home"],
      SelectionDigs.Deepest,
    ),
  );

  expect(pair).toEqual(
    Option.some({ kind: "within", inner: "row", outer: "card" }),
  );
});

test("包む相手の内側の縁までは、上下左右 4 本を引く", () => {
  const distances = DrawnDistancePair.toDistances({
    kind: "within",
    inner: From,
    outer: { left: 0, top: 0, width: 400, height: 300 },
  });

  expect(drawnFacings(distances)).toEqual({
    horizontal: { start: true, end: true },
    vertical: { start: true, end: true },
  });
});

test("包む相手からはみ出した向きには、線を引かない", () => {
  // 左辺が相手の左辺（150）より外にある
  const distances = DrawnDistancePair.toDistances({
    kind: "within",
    inner: From,
    outer: { left: 150, top: 0, width: 250, height: 300 },
  });

  expect(drawnFacings(distances)).toEqual({
    horizontal: { start: false, end: true },
    vertical: { start: true, end: true },
  });
});

test("左右に離れて並ぶ相手までは、離れている向きに 1 本だけ引く", () => {
  const distances = DrawnDistancePair.toDistances({
    kind: "beside",
    from: From,
    to: { left: 260, top: 110, width: 50, height: 30 },
  });

  expect(drawnFacings(distances)).toEqual({
    horizontal: { start: false, end: true },
    vertical: { start: false, end: false },
  });
});

test("斜めに離れている相手までは、線を引かない", () => {
  const distances = DrawnDistancePair.toDistances({
    kind: "beside",
    from: From,
    to: { left: 260, top: 200, width: 50, height: 30 },
  });

  expect(distances).toEqual(FacingDistances.None);
});

test("一部だけ重なる相手までは、線を引かない", () => {
  const distances = DrawnDistancePair.toDistances({
    kind: "beside",
    from: From,
    to: { left: 180, top: 130, width: 50, height: 50 },
  });

  expect(distances).toEqual(FacingDistances.None);
});

test("親子の関係に無く形が包んでいる相手までは、線を引かない", () => {
  const distances = DrawnDistancePair.toDistances({
    kind: "beside",
    from: From,
    to: { left: 0, top: 0, width: 400, height: 300 },
  });

  expect(distances).toEqual(FacingDistances.None);
});

test("接している相手までは、線を引かない", () => {
  const distances = DrawnDistancePair.toDistances({
    kind: "beside",
    from: From,
    to: { left: 200, top: 110, width: 50, height: 30 },
  });

  expect(distances).toEqual(FacingDistances.None);
});

test("どちらかが測れなければ、組にならない", () => {
  const drawn = DistancePair.measure(
    { kind: "beside", from: "row", to: "chip" },
    (name) => (name === "row" ? Option.some(From) : Option.none),
  );

  expect(drawn).toEqual(Option.none);
});

test("指してから Alt を押すと、その指し先が返る", () => {
  const { result } = renderHook(() => useAltPointing());
  act(() => result.current.trackPointer(OnRow));

  holdAlt();

  expect(result.current.pointing).toEqual(Option.some(OnRow));
});

test("Alt を押していない間は、動かしても指し先は返らない", () => {
  const { result } = renderHook(() => useAltPointing());

  act(() => result.current.trackPointer(OnRow));

  expect(result.current.pointing).toEqual(Option.none);
});

test("Alt を離すと指し先は返らなくなる", () => {
  const { result } = renderHook(() => useAltPointing());
  act(() => result.current.trackPointer(OnRow));
  holdAlt();

  releaseAlt();

  expect(result.current.pointing).toEqual(Option.none);
});

test("ウィンドウを離れると、指し先は返らなくなる", () => {
  const { result } = renderHook(() => useAltPointing());
  act(() => result.current.trackPointer(OnRow));
  holdAlt();

  fireEvent.blur(globalThis.window);

  expect(result.current.pointing).toEqual(Option.none);
});

test("入力欄にフォーカスがあるときに Alt を押しても、指し先は返らない", () => {
  const { result } = renderHook(() => useAltPointing());
  const { getByRole } = render(<input type="text" />);
  act(() => result.current.trackPointer(OnRow));

  holdAlt(getByRole("textbox"));

  expect(result.current.pointing).toEqual(Option.none);
});

test("選択欄にフォーカスがあるときに Alt を押しても、指し先は返らない", () => {
  const { result } = renderHook(() => useAltPointing());
  const { getByRole } = render(
    <select>
      <option>fixed</option>
    </select>,
  );
  act(() => result.current.trackPointer(OnRow));

  holdAlt(getByRole("combobox"));

  expect(result.current.pointing).toEqual(Option.none);
});

test("右の Alt を押しても、指し先が返る", () => {
  const { result } = renderHook(() => useAltPointing());
  act(() => result.current.trackPointer(OnRow));

  fireEvent.keyDown(globalThis.document, {
    code: "AltRight",
    key: "Alt",
    altKey: true,
  });

  expect(result.current.pointing).toEqual(Option.some(OnRow));
});

test("左右の Alt を押して片方だけ離しても、指し先は返ったまま", () => {
  const { result } = renderHook(() => useAltPointing());
  act(() => result.current.trackPointer(OnRow));
  holdAlt();
  fireEvent.keyDown(globalThis.document, {
    code: "AltRight",
    key: "Alt",
    altKey: true,
  });

  // 右を押したままなので、左を離した keyup も Alt を押している
  fireEvent.keyUp(globalThis.document, {
    code: "AltLeft",
    key: "Alt",
    altKey: true,
  });

  expect(result.current.pointing).toEqual(Option.some(OnRow));
});

test("一度も指し先を伝えないまま Alt を押すと、キャンバスの外を指していることになる", () => {
  const { result } = renderHook(() => useAltPointing());

  holdAlt();

  expect(result.current.pointing).toEqual(Option.some(Pointing.Outside));
});

test("Alt を押していない間は、指し先が変わっても再レンダーしない", () => {
  const rendered: Option<Pointing>[] = [];
  const { result } = renderHook(() => {
    const control = useAltPointing();
    rendered.push(control.pointing);
    return control;
  });
  const renderedBefore = rendered.length;

  act(() => result.current.trackPointer(OnRow));
  act(() => result.current.trackPointer(OnChip));

  expect(rendered.length).toBe(renderedBefore);
});

test("Alt を押したまま keydown が繰り返し届いても、同じ参照が返る", () => {
  const { result } = renderHook(() => useAltPointing());
  act(() => result.current.trackPointer(OnRow));
  holdAlt();
  const before = result.current.pointing;

  holdAlt();

  expect(result.current.pointing).toBe(before);
});

test("測り直した矩形が前と同じなら、同じ参照を返す", () => {
  drawRowAndAround();
  const selection = selectionDistanceTree(["row"]);
  const { result, rerender } = renderHook(() =>
    useSelectionDistances(selection, Option.some(Pointing.Nothing)),
  );
  const before = result.current;

  rerender();

  expect(result.current).toBe(before);
});

test("指し先が無ければ、DOM を測らずに何も引かない", () => {
  const measured: string[] = [];
  for (const name of ["row", "card"] as const) {
    const element = drawNamed(name, SelectionDistanceTreeBounds[name]);
    const bounds = SelectionDistanceTreeBounds[name];
    element.getBoundingClientRect = () => {
      measured.push(name);
      return new DOMRect(bounds.left, bounds.top, bounds.width, bounds.height);
    };
  }
  const selection = selectionDistanceTree(["row"]);

  const { result } = renderHook(() =>
    useSelectionDistances(selection, Option.none),
  );

  expect(result.current).toEqual(FacingDistances.None);
  expect(measured).toEqual([]);
});

test("測る組が別の組に変わった回は、測り直す前にも前の組の線を返さない", () => {
  drawRowAndAround();
  const { rerender, returned } = renderRecordingDistances(
    Pointing.create(["chip", "card", "home"], SelectionDigs.NoDeeper),
  );
  const changedAt = returned.length;

  rerender({ pointing: Pointing.Nothing });

  expect(returned.slice(changedAt)).not.toContainEqual(rowBesideChip());
});

test("測る組の片方だけが別の名前に変わった回は、測り直す前にも前の組の線を返さない", () => {
  // `row` から `card` の縁まで → `row` から `home` の縁まで
  drawRowAndAround();
  drawNamed("home", SelectionDistanceTreeBounds.home);
  const { rerender, returned } = renderRecordingDistances(Pointing.Nothing);
  const changedAt = returned.length;

  rerender({ pointing: Pointing.create(["home"], SelectionDigs.NoDeeper) });

  expect(returned.slice(changedAt)).not.toContainEqual(
    DrawnDistancePair.toDistances({
      kind: "within",
      inner: SelectionDistanceTreeBounds.row,
      outer: SelectionDistanceTreeBounds.card,
    }),
  );
});

test("測る組が変わっても測った矩形が前と同じなら、新しい組の線を返す", () => {
  // `card` と `home` を同じ矩形に描くので、組の名前だけが変わる
  drawRowAndAround();
  drawNamed("home", SelectionDistanceTreeBounds.card);
  const { rerender, returned } = renderRecordingDistances(Pointing.Nothing);

  rerender({ pointing: Pointing.create(["home"], SelectionDigs.NoDeeper) });

  expect(ArrayEx.last(returned)).toEqual(
    Option.some(
      DrawnDistancePair.toDistances({
        kind: "within",
        inner: SelectionDistanceTreeBounds.row,
        outer: SelectionDistanceTreeBounds.card,
      }),
    ),
  );
});

test("測る対象を変えたあとにウィンドウの大きさが変わると、新しい対象を測り直す", () => {
  /*
   * 前後の対象を同じ矩形に描いておく。前の対象を測り直しても値が変わらないので、
   * 再レンダーが起きず、新しい対象を測り直したかどうかだけが結果に出る。
   */
  const bounds = { left: 12, top: 34, width: 200, height: 100 };
  drawNamed("home", bounds);
  const about = drawNamed("about", bounds);
  const { rerender } = render(<BoundsProbe target={Option.some("home")} />);
  rerender(<BoundsProbe target={Option.some("about")} />);

  stubBounds(about, { left: 20, top: 40, width: 400, height: 200 });
  fireEvent(globalThis.window, new Event("resize"));

  expect(screen.getByTestId("bounds").textContent).toBe("10,20,400,200");
});

test("大きさ 0 で描かれているものは、面積を持つものとしては測れない", () => {
  drawNamed("collapsed", { left: 100, top: 100, width: 0, height: 0 });

  expect(DrawnBounds.measureWithArea("collapsed")).toEqual(Option.none);
});

test("equals は片方だけ値を持てば、比べ方にかかわらず false", () => {
  expect(Option.equals(Option.some("a"), Option.none, () => true)).toBe(false);
  expect(Option.equals(Option.none, Option.some("a"), () => true)).toBe(false);
});

test("Alt を押している間、左右に並ぶ兄弟を指すと、その間の距離が出る", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();

  movePointer(drawn("chip"), Anywhere);
  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual(["40"]);
});

test("Alt を押している間、上下に並ぶ別の枝のノードを指すと、その間の距離が出る", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();

  movePointer(drawn("title"), Anywhere);
  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual(["160"]);
});

test("Alt を押している間、選択の内側を指すと、親の内側の縁までの距離が出る", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();

  movePointer(drawn("label"), Anywhere);
  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual(["10", "120", "180", "20"]);
});

test("⌘ も押して選択の内側を指すと、いちばん内側の子孫から選択の内側の縁までの距離が出る", () => {
  // `label`（左右 170〜220・上下 115〜135）から `row` の縁まで
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();

  movePointer(drawn("label"), Anywhere, "meta");
  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual(["120", "15", "25", "30"]);
});

test("選択が祖先からはみ出している向きには、距離が出ない", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();
  // 左辺が `card` の左辺（120）より外へ出る
  drawnAt("row", { left: 110, top: 100, width: 230, height: 60 });

  movePointer(drawn("label"), Anywhere);
  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual(["10", "120", "180"]);
});

test("自分の artboard の背景を指すと、artboard の内側の縁までの距離が出る", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();

  movePointer(drawn("home"), Anywhere);
  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual(["300", "360", "40", "40"]);
});

test("別の artboard のノードを指すと、親の内側の縁までの距離が出る", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();

  movePointer(drawn("slot"), Anywhere);
  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual(["10", "120", "180", "20"]);
});

test("見出しの上へ移ると、親の内側の縁までの距離に変わる", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();
  movePointer(drawn("chip"), Anywhere);
  holdAlt();
  expect(sortedFacingDistanceLabels()).toEqual(["40"]);

  leavePointerInto(drawn("chip"), artboardHandle("home"));

  expect(sortedFacingDistanceLabels()).toEqual(["10", "120", "180", "20"]);
});

test("リサイズハンドルの上へ移ると、親の内側の縁までの距離に変わる", () => {
  /*
   * `badge`（左右 120〜220・上下 80〜120）の下に `marker`（上辺 160）があり、親 `home` は
   * 左右 100〜460・上下 60〜300（`resize-snap-siblings`）。
   */
  renderCanvas({ selection: setupSelection(["badge"]) });
  drawnApart();
  movePointer(drawn("marker"), Anywhere);
  holdAlt();
  expect(sortedFacingDistanceLabels()).toEqual(["40"]);

  leavePointerInto(drawn("marker"), resizeHandleAt({ x: 1, y: 1 }));

  expect(sortedFacingDistanceLabels()).toEqual(["180", "20", "20", "240"]);
});

test("倍率に合わせて、ドキュメント上の長さで出る", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();
  // 1.2 倍。画面上の 40 はドキュメント上の 33.3…
  wheel(canvasSurface(), { x: 0, y: -100 }, "ctrl");

  movePointer(drawn("chip"), Anywhere);
  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual(["33"]);
});

test("Alt を押してから相手を指しても、距離が出る", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();

  holdAlt();
  movePointer(drawn("chip"), Anywhere);

  expect(sortedFacingDistanceLabels()).toEqual(["40"]);
});

test("Alt を押していない間は、相手を指しても距離が出ない", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();

  movePointer(drawn("chip"), Anywhere);

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("Alt を離すと、距離は消える", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();
  movePointer(drawn("chip"), Anywhere);
  holdAlt();

  releaseAlt();

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("キャンバスに入って空き領域にいる間に Alt を押すと、親の内側の縁までの距離が出る", () => {
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();

  enterPointer(canvasSurface());
  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual(["10", "120", "180", "20"]);
});

test("Alt を押したまま選択を変えると、新しい選択から測り直す", () => {
  const selection = selectionDistanceTree(["row"]);
  const { rerenderWith } = renderCanvas({ selection });
  drawSelectionDistanceTree();
