function pairWith(
  selection: DocumentSelection,
  selected: SelectedNode,
  counterpart: string,
): DistancePair {
  if (counterpart === selected.name) {
    return withinOf(selected, selected.parent);
  }
  if (selected.ancestors.includes(counterpart)) {
    return withinOf(selected, counterpart);
  }
  const counterpartAncestors = DesignDocument.collectAncestorNames(
    selection.document,
    counterpart,
  );
  if (counterpartAncestors.includes(selected.name)) {
    return { kind: "within", inner: counterpart, outer: selected.name };
  }
  return { kind: "beside", from: selected.name, to: counterpart };
}

export function useAltPointing(): AltPointingControl {
  const lastPointing = useRef<Pointing>(Pointing.Outside);
  const [pointing, setPointing] = useState<Option<Pointing>>(Option.none);

  const changeHold = useCallback((isHeld: boolean) => {
    const last = lastPointing.current;
    setPointing((previous) =>
      isHeld ? keepIfSame(previous, last) : Option.none,
    );
  }, []);
  useModifierKeyHold(DistanceModifierKey, changeHold);

  const trackPointer = useCallback((next: Pointing) => {
    lastPointing.current = next;
    setPointing((previous) =>
      Option.isSome(previous) ? keepIfSame(previous, next) : previous,
    );
  }, []);

  return { pointing, trackPointer };
}

export function useModifierKeyHold(
  key: HeldModifierKey,
  onChange: (isHeld: boolean) => void,
): void {
  useEffect(() => {
    const hold = (event: KeyboardEvent) => {
      const startsHold =
        key.shortcut.codes.includes(event.code) &&
        !KeyShortcut.isConsumedBy(key.shortcut, event.target);
      if (startsHold) {
        onChange(true);
      }
    };
    const release = (event: KeyboardEvent) => {
      if (key.isReleasedBy(event)) {
        onChange(false);
      }
    };
    const clear = () => onChange(false);

    globalThis.document.addEventListener("keydown", hold);
    globalThis.document.addEventListener("keyup", release);
    globalThis.window.addEventListener("blur", clear);
    return () => {
      globalThis.document.removeEventListener("keydown", hold);
      globalThis.document.removeEventListener("keyup", release);
      globalThis.window.removeEventListener("blur", clear);
    };
  }, [key, onChange]);
}

export function useMeasured<T>(
  measure: () => Option<T>,
  equals: (value: T, other: T) => boolean,
): Option<T> {
  const [measured, setMeasured] = useState<Option<T>>(Option.none);

  useLayoutEffect(() => {
    const remeasure = () => {
      setMeasured((previous) => {
        const next = measure();
        return Option.equals(previous, next, equals) ? previous : next;
      });
    };

    remeasure();
    /*
     * 購読も毎コミット張り直す。`[]` で 1 度だけ張ると、リスナーが最初の `measure` を
     * 掴んだままになり、測る相手を変えたあとに古い相手を測り続ける。
     */
    globalThis.window.addEventListener("resize", remeasure);
    return () => globalThis.window.removeEventListener("resize", remeasure);
  });

  return measured;
}

/**
 * キャンバスで押された位置から、クリックが選ぶものの名前（docs/06-ui.md「キャンバスのク
 * リックが選ぶ階層」）。選べるノードは `nodeNameAt` で決め、無ければ押された位置を載せて
 * いる artboard へ倒す。ロック中のノードは返さない。
 *
 * @param selection 候補を引くドキュメントと、掘る起点になる今の選択
 * @param names 押された位置から外へ辿った名前（内→外）
 * @param dig 押し方から決まった掘る量
 * @returns 掘った先のノード、無ければ `names` のうち最初の artboard の名前。どちらも無けれ
 *   ば（部品定義の中の名前だけ・空の並び）`none`
 */
nameToSelectAt(
  selection: DocumentSelection,
  names: readonly string[],
  dig: SelectionDig,
): Option<string> {
  return Option.or(
    DocumentSelection.nodeNameAt(selection, names, dig),
    DocumentSelection.artboardNameAt(selection, names),
  );
},

/**
 * キャンバスで押された・指している位置を載せている artboard の名前。
 *
 * @param selection artboard を引くドキュメントの出どころ
 * @param names 押された・指している位置から外へ辿った名前（内→外）
 * @returns `names` のうち最初の artboard の名前。artboard が無ければ（部品定義の中の名前
 *   だけ・空の並び）`none`
 */
artboardNameAt(
  selection: DocumentSelection,
  names: readonly string[],
): Option<string> {
  return ArrayEx.first(
    names.filter((name) =>
      Option.isSome(DesignDocument.findArtboard(selection.document, name)),
    ),
  );
},
